fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of rows and columns in the input matrix
    let rows = arr.len();
    let cols = arr[0].len();

    // Create a matrix with dimensions cols x rows filled with zeros
    let mut result = vec![vec![0i8; rows]; cols];

    // Populate the transpose matrix: result[j][i] = arr[i][j]
    for i in 0..rows {
        for j in 0..cols {
            result[j][i] = arr[i][j];
        }
    }

    result
}